    event Deposit(address indexed user, uint256 amount);
    event Borrow(address indexed user, uint256 amount);
    event Repay(address indexed user, uint256 amount);
    event Withdraw(address indexed user, uint256 amount);

    constructor(address _collateralAsset, address _loanAsset) {
        collateralAsset = IERC20(_collateralAsset);
        loanAsset = IERC20(_loanAsset);
        assetToInterestRate[_loanAsset] = DAILY_INTEREST; // 1% per day
    }

    function depositCollateral(uint256 amount) external {
        require(amount > 0, "Deposit amount must be greater than 0");
        collateralAsset.transferFrom(msg.sender, address(this), amount);
        users[msg.sender].collateralAmount += amount;
        users[msg.sender].lastUpdatedTimestamp = block.timestamp;
        emit Deposit(msg.sender, amount);
    }

    function borrow(uint256 amount) external {
        require(amount > 0, "Borrow amount must be greater than 0");
        User storage user = users[msg.sender];
        require(user.collateralAmount >= amount * 2, "Insufficient collateral");
        loanAsset.transfer(msg.sender, amount);
        user.borrowedAmount += amount;
        user.lastUpdatedTimestamp = block.timestamp;
        emit Borrow(msg.sender, amount);
    }

    function repay(uint256 amount) external {
        require(amount > 0, "Repay amount must be greater than 0");
        User storage user = users[msg.sender];
        uint256 interest = calculateInterest(user.borrowedAmount, user.lastUpdatedTimestamp);
        uint256 totalAmountToRepay = user.borrowedAmount + interest;
        require(amount <= totalAmountToRepay, "Amount to repay exceeds total debt");

        loanAsset.transferFrom(msg.sender, address(this), amount);
        user.borrowedAmount -= amount - interest;
        user.lastUpdatedTimestamp = block.timestamp;

        if (user.borrowedAmount == 0) {
            user.borrowedAmount = 0;
            user.lastUpdatedTimestamp = block.timestamp;
        }

        emit Repay(msg.sender, amount);
    }

    function withdrawCollateral(uint256 amount) external {
        require(amount > 0, "Withdraw amount must be greater than 0");
        User storage user = users[msg.sender];
        require(user.collateralAmount >= amount, "Insufficient collateral");
        require(user.borrowedAmount == 0, "Cannot withdraw collateral if borrowed amount is not zero");
        collateralAsset.transfer(msg.sender, amount);
        user.collateralAmount -= amount;
        emit Withdraw(msg.sender, amount);
    }

    function calculateInterest(uint256 borrowedAmount, uint256 lastUpdatedTimestamp) public view returns (uint256) {
        uint256 timeElapsed = block.timestamp - lastUpdatedTimestamp;
        uint256 interestRate = assetToInterestRate[address(loanAsset)];
        return (borrowedAmount * timeElapsed * interestRate) / (365 days * 1e18);
    }

